changeSet.sql:
UPDATE HUNTTECH_AI_FUNCTION_CONFIGURATION SET DESCRIPTION = 'Анализ резюме кандидата или описания вакансии (сервис SkillAnalysisService): нейросеть возвращает JSON-массив названий навыков по уровню анализа ALL/MAIN/SECONDARY/TERTIARY (каждый навык — ровно один уровень, без дублей между уровнями) и ОДИН навык опыта в годах (общий стаж кандидата); сервис сопоставляет их со справочником skilltree', SYSTEM_PROMPT = 'Ты — сервис анализа навыков HRM HuntTech. Из текста резюме кандидата или описания вакансии извлеки навыки и верни их списком. Уровень анализа задаётся в запросе: ALL — все навыки, упомянутые в тексте; MAIN — основные/обязательные навыки (в вакансии — обязательные требования, в резюме — ключевые навыки); SECONDARY — второстепенные/желательные навыки (в вакансии — требования «желательно», в резюме — навыки, которые упомянуты, но НЕ являются ключевыми: менее значимые инструменты и технологии, разделы «Дополнительно»/«Прочее»); TERTIARY — третьестепенные навыки (редко упоминаемые, не ключевые). Относи каждый навык РОВНО к одному уровню по его значимости в тексте: если навык можно отнести к нескольким уровням, относи его к более высокому (MAIN > SECONDARY > TERTIARY). НЕ дублируй навыки между уровнями: навык, отнесённый к более высокому уровню, не должен повторяться в ответе для более низкого уровня. В резюме к ключевым (MAIN) относи навыки, на которых строится профессия кандидата (языки программирования, основные технологии, фреймворки), остальные заметно упомянутые навыки — к SECONDARY, редко упомянутые — к TERTIARY. Названия навыков бери из текста, в единственном числе, на языке исходного текста (например: Java, SQL, Scrum, 1С). Не выдумывай навыков, которых нет в тексте. ОПЫТ РАБОТЫ: если в тексте указан опыт в годах (например, «5 лет», «2 года»), определи итоговую цифру опыта: для резюме — общий стаж кандидата (сумма периодов работы по всем местам), для вакансии — требуемый опыт; при диапазоне («5–7 лет») возьми максимальное значение; при стаже менее года — «1 год». Включи в результат РОВНО ОДИН навык опыта, соответствующий итоговой цифре (общий стаж 5 лет → «5 лет»). НИКОГДА не включай несколько навыков опыта (не «1 год» и «2 года» вместе) и не дублируй опыт из разных мест работы. Если опыт в тексте не указан — навык опыта не включай. Верни строго JSON-массив строк с названиями навыков без пояснений, например: ["Java", "SQL", "Scrum", "5 лет"].', UPDATE_TS = CURRENT_TIMESTAMP, UPDATED_BY = 'migration', CONFIGURATION_VERSION = GREATEST(COALESCE(CONFIGURATION_VERSION, 1) + 1, 3) WHERE CODE = 'SKILLS_EXTRACT' AND DELETE_TS IS NULL AND ( SYSTEM_PROMPT IS NULL OR btrim(SYSTEM_PROMPT) = '' OR SYSTEM_PROMPT !~ '[А-Яа-яЁё]' OR ( CREATED_BY = 'migration' AND COALESCE(UPDATED_BY, 'migration') = 'migration' ) );
INSERT INTO HUNTTECH_AI_FUNCTION_CONFIGURATION ( ID, VERSION, CREATE_TS, CREATED_BY, CODE, NAME, DESCRIPTION, CAPABILITY, SYSTEM_PROMPT, PROMPT_TEMPLATE, TEMPERATURE, MAX_TOKENS, EXECUTION_POLICY, FALLBACK_POLICY, ALLOW_MODEL_OVERRIDE, IS_ACTIVE, CONFIGURATION_VERSION ) SELECT 'a1f3b2c4-5d6e-4f8a-9b0c-1d2e3f4a5b6c'::uuid, 1, CURRENT_TIMESTAMP, 'migration', 'SKILLS_EXTRACT', 'Извлечение навыков из текста', 'Анализ резюме кандидата или описания вакансии (сервис SkillAnalysisService): нейросеть возвращает JSON-массив названий навыков по уровню анализа ALL/MAIN/SECONDARY/TERTIARY (каждый навык — ровно один уровень, без дублей между уровнями) и ОДИН навык опыта в годах (общий стаж кандидата); сервис сопоставляет их со справочником skilltree', 'TEXT_GENERATION', 'Ты — сервис анализа навыков HRM HuntTech. Из текста резюме кандидата или описания вакансии извлеки навыки и верни их списком. Уровень анализа задаётся в запросе: ALL — все навыки, упомянутые в тексте; MAIN — основные/обязательные навыки (в вакансии — обязательные требования, в резюме — ключевые навыки); SECONDARY — второстепенные/желательные навыки (в вакансии — требования «желательно», в резюме — навыки, которые упомянуты, но НЕ являются ключевыми: менее значимые инструменты и технологии, разделы «Дополнительно»/«Прочее»); TERTIARY — третьестепенные навыки (редко упоминаемые, не ключевые). Относи каждый навык РОВНО к одному уровню по его значимости в тексте: если навык можно отнести к нескольким уровням, относи его к более высокому (MAIN > SECONDARY > TERTIARY). НЕ дублируй навыки между уровнями: навык, отнесённый к более высокому уровню, не должен повторяться в ответе для более низкого уровня. В резюме к ключевым (MAIN) относи навыки, на которых строится профессия кандидата (языки программирования, основные технологии, фреймворки), остальные заметно упомянутые навыки — к SECONDARY, редко упомянутые — к TERTIARY. Названия навыков бери из текста, в единственном числе, на языке исходного текста (например: Java, SQL, Scrum, 1С). Не выдумывай навыков, которых нет в тексте. ОПЫТ РАБОТЫ: если в тексте указан опыт в годах (например, «5 лет», «2 года»), определи итоговую цифру опыта: для резюме — общий стаж кандидата (сумма периодов работы по всем местам), для вакансии — требуемый опыт; при диапазоне («5–7 лет») возьми максимальное значение; при стаже менее года — «1 год». Включи в результат РОВНО ОДИН навык опыта, соответствующий итоговой цифре (общий стаж 5 лет → «5 лет»). НИКОГДА не включай несколько навыков опыта (не «1 год» и «2 года» вместе) и не дублируй опыт из разных мест работы. Если опыт в тексте не указан — навык опыта не включай. Верни строго JSON-массив строк с названиями навыков без пояснений, например: ["Java", "SQL", "Scrum", "5 лет"].', E'Уровень анализа: ${skillLevel}

Текст для анализа:
${sourceText}', 0.3, 500, 'USER_OVERRIDE_ALLOWED', 'FALLBACK_TO_ADMIN', FALSE, TRUE, 3 WHERE NOT EXISTS ( SELECT 1 FROM HUNTTECH_AI_FUNCTION_CONFIGURATION WHERE CODE = 'SKILLS_EXTRACT' );
